	if err != nil {
		return nil, err
	}

	// 4) Convert userDB → db.User
	user := &db.User{
		ID:        userDB.ID,
		FullName:  userDB.FullName,
		Email:     userDB.Email,
		Phone:     userDB.Phone,
		RoleID:    userDB.RoleID,
		CreatedAt: userDB.CreatedAt,
		UpdatedAt: userDB.UpdatedAt,
	}

